Mono<Ksiazka> findById(long id) {
    return client.sql("SELECT id, tytul, autor FROM ksiazki WHERE id = :id")
        .bind("id", id)
        .map((row, meta) -> new Ksiazka(
            row.get("id", Long.class), row.get("tytul", String.class),
            row.get("autor", String.class)))
        .one();
}

@PostMapping
Mono<ResponseEntity<Ksiazka>> create(@Valid @RequestBody Mono<NowaKsiazka> body) {
    return body.flatMap(service::save)
        .map(saved -> ResponseEntity.status(HttpStatus.CREATED).body(saved));
}

Mono<ResponseEntity<Void>> delete(long id) {
    return client.sql("DELETE FROM ksiazki WHERE id = :id")
        .bind("id", id).fetch().rowsUpdated()
        .map(count -> count == 0
            ? ResponseEntity.notFound().<Void>build()
            : ResponseEntity.noContent().<Void>build());
}

@DeleteMapping("/{id}")
Mono<Void> delete(@PathVariable long id) {
    return client.sql("DELETE FROM ksiazki WHERE id = :id")
        .bind("id", id).then();
}

@DeleteMapping("/{id}")
Mono<ResponseEntity<Void>> delete(@PathVariable long id) {
    return service.delete(id) // Mono<Long>: liczba zmienionych wierszy
        .map(count -> count == 0
            ? ResponseEntity.notFound().<Void>build()
            : ResponseEntity.noContent().<Void>build());
}
